// Business models: plain TypeScript types, independent from TypeORM and from
// the HTTP layer (same convention as the customers module).

// A bike as returned by the service
export interface BikeModel {
  id: string;
  brand: string;
  model: string;
  description: string;
  category: string;
  frameMaterial: string;
  frameSizeCm: number;
  wheelSizeInches: number;
  gearCount: number;
  weightKg: number;
  electric: boolean;
  priceCents: number; // price in cents to avoid floating point errors
}

// Data needed to create a bike (no id: it is generated by the database)
export interface CreateBikeModel {
  brand: string;
  model: string;
  description: string;
  category: string;
  frameMaterial: string;
  frameSizeCm: number;
  wheelSizeInches: number;
  gearCount: number;
  weightKg: number;
  electric: boolean;
  priceCents: number;
}

// PATCH = partial update: every field is optional
export type UpdateBikeModel = Partial<CreateBikeModel>;

// One page of the catalogue + the total number of bikes in the database
export interface BikesPageModel {
  totalCount: number;
  bikes: BikeModel[];
}